import { useState, useContext, useCallback } from 'react';
import { GlobalStateContext, SettingsContext, GameInfoContext } from '../contexts';
import { BELT_IDS, SORTER_IDS, BUILDING_NAME_TO_ID } from './constants.js';
import { layoutProductionChain } from './layout_engine.js';
import { createEmptyBlueprint, encodeBlueprintString } from './blueprint_encoder.js';

const BELT_OPTIONS = [
    { label: '传送带 Mk.I', value: BELT_IDS.MK1 },
    { label: '传送带 Mk.II', value: BELT_IDS.MK2 },
    { label: '传送带 Mk.III', value: BELT_IDS.MK3 },
];

const SORTER_OPTIONS = [
    { label: '分拣器 Mk.I', value: SORTER_IDS.MK1 },
    { label: '分拣器 Mk.II', value: SORTER_IDS.MK2 },
    { label: '分拣器 Mk.III', value: SORTER_IDS.MK3 },
];

export function BlueprintPanel({ resultDict, needsList }) {
    const global_state = useContext(GlobalStateContext);
    const settings = useContext(SettingsContext);
    const game_info = useContext(GameInfoContext);

    const [beltTier, setBeltTier] = useState(BELT_IDS.MK3);
    const [sorterTier, setSorterTier] = useState(SORTER_IDS.MK2);
    const [blueprintStr, setBlueprintStr] = useState('');
    const [copied, setCopied] = useState(false);
    const [error, setError] = useState(null);

    const generate = useCallback(() => {
        try {
            setError(null);
            const { item_graph, item_data, game_data, scheme_data } = global_state;
            const mineralize_list = settings.mineralize_list;
            const time_tick = settings.is_time_unit_minute ? 60 : 1;

            // Build chain input from result_dict
            const items = {};
            const topologicalOrder = [];
            const externalInputs = [];
            const finalOutputs = Object.keys(needsList);

            // Use item_list (topological order) from global_state
            for (const itemName of global_state.item_list) {
                if (!(itemName in resultDict) || resultDict[itemName] < 1e-6) continue;

                const recipe_id = item_data[itemName][scheme_data.item_recipe_choices[itemName]];
                const recipe = game_data.recipe_data[recipe_id];
                const recipeInputs = Object.keys(recipe['原料']);

                // Items with no recipe inputs or mineralized = external
                if (recipeInputs.length === 0 || itemName in mineralize_list) {
                    externalInputs.push(itemName);
                    continue;
                }

                const factory_info = game_data.factory_data[recipe['设施']][scheme_data.scheme_for_recipe[recipe_id]['建筑']];
                const factory_per_yield = 1 / item_graph[itemName]['产出倍率'] / factory_info['倍率'];
                const machineCount = Math.ceil(resultDict[itemName] / time_tick * factory_per_yield);

                if (machineCount <= 0) continue;

                items[itemName] = {
                    amount: resultDict[itemName],
                    recipeInputs: recipeInputs.filter(m => !(m in mineralize_list)),
                    buildingName: factory_info['名称'],
                    machineCount,
                };
                topologicalOrder.push(itemName);
            }

            // Add mineralized inputs that are also recipe inputs
            for (const itemName of Object.keys(mineralize_list)) {
                if (!externalInputs.includes(itemName)) {
                    externalInputs.push(itemName);
                }
            }

            const chainResult = layoutProductionChain({
                items,
                topologicalOrder,
                externalInputs,
                finalOutputs,
                beltItemId: beltTier,
                sorterItemId: sorterTier,
            });

            const bp = createEmptyBlueprint({ shortDesc: 'DSP-Calc Blueprint' });
            bp.buildings = chainResult.buildings;
            const str = encodeBlueprintString(bp);
            setBlueprintStr(str);
        } catch (e) {
            setError(e.message);
            console.error('Blueprint generation failed:', e);
        }
    }, [global_state, settings, resultDict, needsList, beltTier, sorterTier]);

    const copyToClipboard = useCallback(() => {
        navigator.clipboard.writeText(blueprintStr).then(() => {
            setCopied(true);
            setTimeout(() => setCopied(false), 2000);
        });
    }, [blueprintStr]);

    return (
        <div className="blueprint-panel p-3 border rounded mt-3">
            <h5>蓝图生成</h5>
            <div className="d-flex gap-3 mb-3">
                <div>
                    <label className="form-label small">传送带</label>
                    <select className="form-select form-select-sm"
                            value={beltTier} onChange={e => setBeltTier(Number(e.target.value))}>
                        {BELT_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                    </select>
                </div>
                <div>
                    <label className="form-label small">分拣器</label>
                    <select className="form-select form-select-sm"
                            value={sorterTier} onChange={e => setSorterTier(Number(e.target.value))}>
                        {SORTER_OPTIONS.map(o => <option key={o.value} value={o.value}>{o.label}</option>)}
                    </select>
                </div>
                <div className="d-flex align-items-end">
                    <button className="btn btn-primary btn-sm" onClick={generate}>
                        生成蓝图
                    </button>
                </div>
            </div>
            {error && <div className="alert alert-danger small">{error}</div>}
            {blueprintStr && (
                <div>
                    <div className="d-flex gap-2 mb-2">
                        <button className="btn btn-outline-secondary btn-sm" onClick={copyToClipboard}>
                            {copied ? '已复制!' : '复制到剪贴板'}
                        </button>
                        <a className="btn btn-outline-info btn-sm"
                           href="https://huww98.github.io/dsp_blueprint_editor/"
                           target="_blank" rel="noopener noreferrer">
                            在编辑器中预览
                        </a>
                    </div>
                    <textarea className="form-control font-monospace small"
                              rows={3} readOnly value={blueprintStr}/>
                </div>
            )}
        </div>
    );
}
