- [ ] **Step 3: Implement md5f.js**

Create `dsp-calc/src/blueprint/md5f.js`. This is a port of the MD5F algorithm from huww98's `md5.ts`. The key differences from standard MD5:

- Initial vector A: `0x67452301` (same)
- Initial vector B: `0xEFDCAB89` (standard is `0xEFCDAB89` — swapped C and D bytes)
- Initial vector C: `0x98BADCFE` (same)
- Initial vector D: `0x10325746` (standard is `0x10325476` — swapped 5 and 7 bytes)
- Several K-constants in the table are modified

Fetch the exact implementation from https://github.com/huww98/dsp_blueprint_editor/blob/master/src/blueprint/md5.ts and port it to plain JS. The file exports one function:

```js
/**
 * Compute MD5F hash of a string. Returns uppercase 32-char hex string.
 * MD5F is a custom MD5 variant used by Dyson Sphere Program blueprints.
 * Ported from huww98/dsp_blueprint_editor.
 */
export function md5f(str) {
    // Convert string to UTF-8 byte array
    const encoder = new TextEncoder();
    const data = encoder.encode(str);

    // MD5 padding
    const bitLen = data.length * 8;
    const padLen = (data.length % 64 < 56)
        ? 56 - data.length % 64
        : 120 - data.length % 64;
    const padded = new Uint8Array(data.length + padLen + 8);
    padded.set(data);
    padded[data.length] = 0x80;
    const view = new DataView(padded.buffer);
    view.setUint32(padded.length - 8, bitLen & 0xFFFFFFFF, true);
    view.setUint32(padded.length - 4, Math.floor(bitLen / 0x100000000), true);

    // Modified initial vectors (MD5F differs from standard MD5 here)
    let a0 = 0x67452301;
    let b0 = 0xEFDCAB89;  // standard MD5: 0xEFCDAB89
    let c0 = 0x98BADCFE;
    let d0 = 0x10325746;  // standard MD5: 0x10325476

    // K table — mostly same as standard MD5, with specific modifications
    // Port the exact K table from huww98's md5.ts
    const K = [
        // ... (full 64-element K table from huww98's source)
    ];

    // S table (same as standard MD5)
    const S = [
        7,12,17,22, 7,12,17,22, 7,12,17,22, 7,12,17,22,
        5, 9,14,20, 5, 9,14,20, 5, 9,14,20, 5, 9,14,20,
        4,11,16,23, 4,11,16,23, 4,11,16,23, 4,11,16,23,
        6,10,15,21, 6,10,15,21, 6,10,15,21, 6,10,15,21,
    ];

    // Process each 64-byte block
    for (let offset = 0; offset < padded.length; offset += 64) {
        const M = new Uint32Array(16);
        for (let j = 0; j < 16; j++) {
            M[j] = view.getUint32(offset + j * 4, true);
        }

        let A = a0, B = b0, C = c0, D = d0;

        for (let i = 0; i < 64; i++) {
            let F, g;
            if (i < 16) {
                F = (B & C) | (~B & D);
                g = i;
            } else if (i < 32) {
                F = (D & B) | (~D & C);
                g = (5 * i + 1) % 16;
            } else if (i < 48) {
                F = B ^ C ^ D;
                g = (3 * i + 5) % 16;
            } else {
                F = C ^ (B | ~D);
                g = (7 * i) % 16;
            }
            F = (F + A + K[i] + M[g]) | 0;
            A = D;
            D = C;
            C = B;
            B = (B + ((F << S[i]) | (F >>> (32 - S[i])))) | 0;
        }

        a0 = (a0 + A) | 0;
        b0 = (b0 + B) | 0;
        c0 = (c0 + C) | 0;
        d0 = (d0 + D) | 0;
    }

    // Format as uppercase hex
    function toHex(n) {
        return ((n >>> 0).toString(16).padStart(8, '0'))
            .match(/../g).reverse().join('').toUpperCase();
    }
    return toHex(a0) + toHex(b0) + toHex(c0) + toHex(d0);
}
```

**Important:** The exact K table values must be fetched from huww98's `md5.ts` at https://github.com/huww98/dsp_blueprint_editor/blob/master/src/blueprint/md5.ts — the modified constants are what make MD5F different from standard MD5. Do not use standard MD5 K constants.

