- [ ] **Step 3: Implement blueprint_encoder.js**

Create `dsp-calc/src/blueprint/blueprint_encoder.js`. Port the serialization logic from huww98's `parser.ts` `toStr()` function and related helpers.

```js
import pako from 'pako';
import { md5f } from './md5f.js';

/**
 * Create an empty blueprint data structure.
 * @param {Object} options
 * @param {string} options.shortDesc - Blueprint name
 * @param {string} [options.desc=''] - Blueprint description
 * @param {string} [options.gameVersion='0.10.33.24052'] - Game version
 * @returns {Object} BlueprintData
 */
export function createEmptyBlueprint({ shortDesc, desc = '', gameVersion = '0.10.33.24052' }) {
    return {
        header: {
            layout: 10,
            icons: [0, 0, 0, 0, 0],
            time: new Date(),
            gameVersion,
            shortDesc,
            desc,
        },
        version: 1,
        cursorOffset: { x: 0, y: 0 },
        cursorTargetArea: 0,
        dragBoxSize: { x: 1, y: 1 },
        primaryAreaIdx: 0,
        areas: [{
            index: 0,
            parentIndex: -1,
            tropicAnchor: 0,
            areaSegments: 200,
            anchorLocalOffset: { x: 0, y: 0 },
            size: { x: 1, y: 1 },
        }],
        buildings: [],
    };
}

/**
 * Encode a BlueprintData object into a valid DSP blueprint string.
 * @param {Object} bp - BlueprintData
 * @returns {string} Blueprint string pasteable into the game
 */
export function encodeBlueprintString(bp) {
    const header = buildHeader(bp.header);
    const content = buildContent(bp);
    const compressed = pako.gzip(content);
    const base64 = uint8ArrayToBase64(compressed);
    const beforeHash = header + '"' + base64 + '"';
    const hash = md5f(header + '"' + base64);
    return beforeHash + hash;
}

function buildHeader(h) {
    const ticks = dateToTicks(h.time);
    const shortDesc = encodeURIComponent(h.shortDesc);
    const desc = encodeURIComponent(h.desc);
    return `BLUEPRINT:0,${h.layout},${h.icons.join(',')},0,${ticks},${h.gameVersion},${shortDesc},${desc}`;
}

function dateToTicks(date) {
    // .NET ticks = (Unix ms + epoch offset) * 10000
    // Epoch offset: 621355968000000000 ticks from 0001-01-01 to 1970-01-01
    const unixMs = date.getTime();
    const ticks = BigInt(unixMs) * 10000n + 621355968000000000n;
    return ticks.toString();
}

function buildContent(bp) {
    const parts = [];

    // Header: 7 x int32 + 1 x uint8
    const headerBuf = new ArrayBuffer(29);
    const headerView = new DataView(headerBuf);
    headerView.setInt32(0, bp.version, true);
    headerView.setInt32(4, bp.cursorOffset.x, true);
    headerView.setInt32(8, bp.cursorOffset.y, true);
    headerView.setInt32(12, bp.cursorTargetArea, true);
    headerView.setInt32(16, bp.dragBoxSize.x, true);
    headerView.setInt32(20, bp.dragBoxSize.y, true);
    headerView.setInt32(24, bp.primaryAreaIdx, true);
    headerView.setUint8(28, bp.areas.length);
    parts.push(new Uint8Array(headerBuf));

    // Areas: 14 bytes each
    for (const area of bp.areas) {
        const areaBuf = new ArrayBuffer(14);
        const areaView = new DataView(areaBuf);
        areaView.setUint8(0, area.index);
        areaView.setUint8(1, area.parentIndex & 0xFF);
        areaView.setInt16(2, area.tropicAnchor, true);
        areaView.setInt16(4, area.areaSegments, true);
        areaView.setInt16(6, area.anchorLocalOffset.x, true);
        areaView.setInt16(8, area.anchorLocalOffset.y, true);
        areaView.setInt16(10, area.size.x, true);
        areaView.setInt16(12, area.size.y, true);
        parts.push(new Uint8Array(areaBuf));
    }

    // Building count: int32
    const countBuf = new ArrayBuffer(4);
    new DataView(countBuf).setInt32(0, bp.buildings.length, true);
    parts.push(new Uint8Array(countBuf));

    // Buildings: 61 + 4*paramCount bytes each
    for (const b of bp.buildings) {
        const paramCount = b.parameters ? b.parameters.length : 0;
        const bldBuf = new ArrayBuffer(61 + 4 * paramCount);
        const v = new DataView(bldBuf);
        let offset = 0;

        v.setInt32(offset, b.index, true); offset += 4;
        v.setInt8(offset, b.areaIndex); offset += 1;

        v.setFloat32(offset, b.localOffset[0].x, true); offset += 4;
        v.setFloat32(offset, b.localOffset[0].y, true); offset += 4;
        v.setFloat32(offset, b.localOffset[0].z, true); offset += 4;
        v.setFloat32(offset, b.localOffset[1].x, true); offset += 4;
        v.setFloat32(offset, b.localOffset[1].y, true); offset += 4;
        v.setFloat32(offset, b.localOffset[1].z, true); offset += 4;

        v.setFloat32(offset, b.yaw[0], true); offset += 4;
        v.setFloat32(offset, b.yaw[1], true); offset += 4;

        v.setInt16(offset, b.itemId, true); offset += 2;
        v.setInt16(offset, b.modelIndex, true); offset += 2;

        v.setInt32(offset, b.outputObjIdx, true); offset += 4;
        v.setInt32(offset, b.inputObjIdx, true); offset += 4;

        v.setInt8(offset, b.outputToSlot); offset += 1;
        v.setInt8(offset, b.inputFromSlot); offset += 1;
        v.setInt8(offset, b.outputFromSlot); offset += 1;
        v.setInt8(offset, b.inputToSlot); offset += 1;
        v.setInt8(offset, b.outputOffset); offset += 1;
        v.setInt8(offset, b.inputOffset); offset += 1;

        v.setInt16(offset, b.recipeId, true); offset += 2;
        v.setInt16(offset, b.filterId, true); offset += 2;
        v.setInt16(offset, paramCount, true); offset += 2;

        if (b.parameters) {
            for (let i = 0; i < paramCount; i++) {
                v.setInt32(offset, b.parameters[i], true); offset += 4;
            }
        }

        parts.push(new Uint8Array(bldBuf));
    }

    // Concatenate all parts
    const totalLen = parts.reduce((sum, p) => sum + p.length, 0);
    const result = new Uint8Array(totalLen);
    let pos = 0;
    for (const p of parts) {
        result.set(p, pos);
        pos += p.length;
    }
    return result;
}

function uint8ArrayToBase64(bytes) {
    let binary = '';
    for (let i = 0; i < bytes.length; i++) {
        binary += String.fromCharCode(bytes[i]);
    }
    return btoa(binary);
}
