```js
import { BUILDING_SIZE } from './constants.js';

/**
 * Generate a single production unit: N machines in a row with input/output belts and sorters.
 *
 * Layout (single row, ≤2 inputs):
 *   input belt 0  ═══════►
 *     ↕ sorter      ↕ sorter
 *   [machine 0] [machine 1] ...
 *     ↕ sorter      ↕ sorter
 *   input belt 1  ═══════►  (if 2 inputs)
 *     ↕ sorter      ↕ sorter
 *   output belt   ◄═══════
 *
 * @param {Object} params
 * @param {number} params.buildingItemId - Item ID for production building
 * @param {number} params.recipeId - Recipe ID to assign
 * @param {number} params.machineCount - Number of machines
 * @param {string[]} params.inputItems - Input item names (for tracking ports)
 * @param {string[]} params.outputItems - Output item names (for tracking ports)
 * @param {number} params.beltItemId - Belt tier item ID
 * @param {number} params.sorterItemId - Sorter tier item ID
 * @returns {{ buildings: Object[], inputPorts: Object[], outputPorts: Object[], width: number, height: number }}
 */
export function layoutProductionUnit({
    buildingItemId,
    recipeId,
    machineCount,
    inputItems,
    outputItems,
    beltItemId,
    sorterItemId,
}) {
    const buildings = [];
    const inputPorts = [];
    const outputPorts = [];
    let nextIndex = 0;

    const bSize = BUILDING_SIZE[buildingItemId] || { w: 3, h: 3 };
    const machineSpacing = bSize.w; // grid units between machine centers

    // Y positions for rows (bottom to top):
    // Row 0: output belt     y = 0
    // Row 1: machines         y = bSize.h
    // Row 2+: input belts     y = bSize.h * 2, bSize.h * 2 + 1, ...
    const outputBeltY = 0;
    const machineY = bSize.h;
    const inputBeltStartY = bSize.h * 2;

    // Place input belts
    const inputBeltIndices = []; // per input item: array of belt building indices
    for (let inputIdx = 0; inputIdx < inputItems.length; inputIdx++) {
        const beltY = inputBeltStartY + inputIdx;
        const beltIndices = [];
        for (let m = 0; m < machineCount; m++) {
            const x = m * machineSpacing;
            const idx = nextIndex++;
            buildings.push(makeBelt(idx, x, beltY, 0, beltItemId));
            beltIndices.push(idx);
        }
        // Connect belts in sequence
        for (let i = 0; i < beltIndices.length - 1; i++) {
            buildings[beltIndices[i]].outputObjIdx = beltIndices[i + 1];
            buildings[beltIndices[i + 1]].inputObjIdx = beltIndices[i];
        }
        inputBeltIndices.push(beltIndices);
        inputPorts.push({
            item: inputItems[inputIdx],
            beltIndex: beltIndices[0],
            position: { x: 0, y: beltY, z: 0 },
        });
    }

    // Place machines
    const machineIndices = [];
    for (let m = 0; m < machineCount; m++) {
        const x = m * machineSpacing;
        const idx = nextIndex++;
        buildings.push({
            index: idx,
            areaIndex: 0,
            localOffset: [{ x, y: machineY, z: 0 }, { x, y: machineY, z: 0 }],
            yaw: [0, 0],
            itemId: buildingItemId,
            modelIndex: 0,
            outputObjIdx: -1,
            inputObjIdx: -1,
            outputToSlot: 0,
            inputFromSlot: 0,
            outputFromSlot: 0,
            inputToSlot: 0,
            outputOffset: 0,
            inputOffset: 0,
            recipeId,
            filterId: 0,
            parameters: null,
        });
        machineIndices.push(idx);
    }

    // Place output belts
    const outputBeltIndices = [];
    for (let m = 0; m < machineCount; m++) {
        const x = m * machineSpacing;
        const idx = nextIndex++;
        buildings.push(makeBelt(idx, x, outputBeltY, 180, beltItemId)); // 180° = reverse direction
        outputBeltIndices.push(idx);
    }
    // Connect output belts in reverse (right to left)
    for (let i = outputBeltIndices.length - 1; i > 0; i--) {
        buildings[outputBeltIndices[i]].outputObjIdx = outputBeltIndices[i - 1];
        buildings[outputBeltIndices[i - 1]].inputObjIdx = outputBeltIndices[i];
    }
    outputPorts.push({
        item: outputItems[0],
        beltIndex: outputBeltIndices[0],
        position: { x: 0, y: outputBeltY, z: 0 },
    });

    // Place sorters: connect input belts to machines, machines to output belts
    for (let m = 0; m < machineCount; m++) {
        // Input sorters
        for (let inputIdx = 0; inputIdx < inputItems.length; inputIdx++) {
            const beltIdx = inputBeltIndices[inputIdx][m];
            const machIdx = machineIndices[m];
            const beltPos = buildings[beltIdx].localOffset[0];
            const machPos = buildings[machIdx].localOffset[0];
            const idx = nextIndex++;
            buildings.push(makeSorter(idx, beltPos, machPos, sorterItemId, beltIdx, machIdx));
        }
        // Output sorter
        {
            const machIdx = machineIndices[m];
            const beltIdx = outputBeltIndices[m];
            const machPos = buildings[machIdx].localOffset[0];
            const beltPos = buildings[beltIdx].localOffset[0];
            const idx = nextIndex++;
            buildings.push(makeSorter(idx, machPos, beltPos, sorterItemId, machIdx, beltIdx));
        }
    }

    const width = machineCount * machineSpacing;
    const height = inputBeltStartY + inputItems.length;

    return { buildings, inputPorts, outputPorts, width, height };
}

function makeBelt(index, x, y, yaw, beltItemId) {
    return {
        index,
        areaIndex: 0,
        localOffset: [{ x, y, z: 0 }, { x, y, z: 0 }],
        yaw: [yaw, yaw],
        itemId: beltItemId,
        modelIndex: 0,
        outputObjIdx: -1,
        inputObjIdx: -1,
        outputToSlot: 1,
        inputFromSlot: 1,
        outputFromSlot: 0,
        inputToSlot: 0,
        outputOffset: 0,
        inputOffset: 0,
        recipeId: 0,
        filterId: 0,
        parameters: null,
    };
}

function makeSorter(index, fromPos, toPos, sorterItemId, fromIdx, toIdx) {
    return {
        index,
        areaIndex: 0,
        localOffset: [
            { x: fromPos.x, y: fromPos.y, z: 0 },
            { x: toPos.x, y: toPos.y, z: 0 },
        ],
        yaw: [0, 0],
        itemId: sorterItemId,
        modelIndex: 0,
        outputObjIdx: toIdx,
        inputObjIdx: fromIdx,
        outputToSlot: 0,
        inputFromSlot: 0,
        outputFromSlot: 0,
        inputToSlot: 0,
        outputOffset: 0,
        inputOffset: 0,
        recipeId: 0,
        filterId: 0,
        parameters: null,
    };
}
```

**Note:** The exact grid coordinates (spacing, slot assignments, yaw angles) will need to be calibrated against in-game behavior during implementation. The structure above is a starting scaffold — import the generated blueprint into huww98's editor and adjust coordinates until buildings align correctly.

