```js
import { BUILDING_NAME_TO_ID, BUILDING_SIZE, BELT_THROUGHPUT } from './constants.js';

/**
 * Lay out a full production chain: multiple units stacked vertically,
 * connected by belts from upstream output to downstream input.
 *
 * @param {Object} params
 * @param {Object} params.items - Dict of item name → { amount, recipeInputs, buildingName, machineCount }
 * @param {string[]} params.topologicalOrder - Items sorted upstream-first
 * @param {string[]} params.externalInputs - Items that come from outside (ores, mineralized)
 * @param {string[]} params.finalOutputs - Target products
 * @param {number} params.beltItemId - Belt tier
 * @param {number} params.sorterItemId - Sorter tier
 * @returns {{ buildings: Object[], inputPorts: Object[], outputPorts: Object[] }}
 */
export function layoutProductionChain({
    items,
    topologicalOrder,
    externalInputs,
    finalOutputs,
    beltItemId,
    sorterItemId,
}) {
    const allBuildings = [];
    const allInputPorts = [];
    const allOutputPorts = [];
    let globalIndex = 0;
    let currentY = 0;

    // Map from item name → its output port (for connecting downstream)
    const itemOutputPorts = {};

    for (const itemName of topologicalOrder) {
        const info = items[itemName];
        const buildingItemId = BUILDING_NAME_TO_ID[info.buildingName];
        if (!buildingItemId) continue;

        const unit = layoutProductionUnit({
            buildingItemId,
            recipeId: 0, // Will be resolved at integration time from scheme_data
            machineCount: info.machineCount,
            inputItems: info.recipeInputs,
            outputItems: [itemName],
            beltItemId,
            sorterItemId,
        });

        // Offset all buildings by currentY and reindex
        const indexOffset = globalIndex;
        for (const b of unit.buildings) {
            b.index += indexOffset;
            b.localOffset[0].y += currentY;
            b.localOffset[1].y += currentY;
            if (b.outputObjIdx >= 0) b.outputObjIdx += indexOffset;
            if (b.inputObjIdx >= 0) b.inputObjIdx += indexOffset;
            allBuildings.push(b);
        }

        // Track ports with offset
        for (const port of unit.inputPorts) {
            port.beltIndex += indexOffset;
            port.position.y += currentY;
            if (externalInputs.includes(port.item)) {
                allInputPorts.push(port);
            }
            // If this input comes from an upstream unit, connect belts
            if (itemOutputPorts[port.item]) {
                const upstreamPort = itemOutputPorts[port.item];
                const upstreamBelt = allBuildings[upstreamPort.beltIndex];
                const downstreamBelt = allBuildings[port.beltIndex];
                // Connect upstream output to downstream input via belt chain
                // For MVP, direct connection (may need intermediate belts later)
                upstreamBelt.outputObjIdx = port.beltIndex;
                downstreamBelt.inputObjIdx = upstreamPort.beltIndex;
            }
        }

        for (const port of unit.outputPorts) {
            port.beltIndex += indexOffset;
            port.position.y += currentY;
            itemOutputPorts[port.item] = port;
            if (finalOutputs.includes(port.item)) {
                allOutputPorts.push(port);
            }
        }

        globalIndex += unit.buildings.length;
        currentY += unit.height + 2; // 2 grid gap between units
    }

    return {
        buildings: allBuildings,
        inputPorts: allInputPorts,
        outputPorts: allOutputPorts,
    };
}
```

