## Part 1: layoutProductionUnit (Task 5)

A function that lays out ONE recipe's worth of buildings: N machines in a row with input/output belts and sorters.

**Layout pattern (single row, ≤2 inputs):**
```
input belt 0  ═══════►
  ↕ sorter
[machine 0] [machine 1] ...
  ↕ sorter
input belt 1  ═══════► (if 2 inputs)
  ↕ sorter
output belt   ◄═══════
```

**Function signature:**
```js
export function layoutProductionUnit({
    buildingItemId,  // e.g. 2303 (Assembler Mk.I)
    recipeId,        // recipe ID to assign to machines
    machineCount,    // number of machines
    inputItems,      // string[] — input item names (for port tracking)
    outputItems,     // string[] — output item names (for port tracking)
    beltItemId,      // belt tier item ID (2001/2002/2003)
    sorterItemId,    // sorter tier item ID (2011/2012/2013)
}) => { buildings: Building[], inputPorts: Port[], outputPorts: Port[], width: number, height: number }
```

**Building structure** (each element of buildings[]):
```js
{
    index: number,
    areaIndex: 0,
    localOffset: [{x, y, z}, {x, y, z}],  // position pair
    yaw: [number, number],                  // rotation pair
    itemId: number,       // building type
    modelIndex: 0,
    outputObjIdx: number, // index of output-connected building (-1 if none)
    inputObjIdx: number,  // index of input-connected building (-1 if none)
    outputToSlot: number,
    inputFromSlot: number,
    outputFromSlot: number,
    inputToSlot: number,
    outputOffset: number,
    inputOffset: number,
    recipeId: number,
    filterId: number,
    parameters: null,
}
```

**Port structure:**
```js
{ item: string, beltIndex: number, position: {x, y, z} }
```

## Part 2: layoutProductionChain (Task 6)

A function that lays out a FULL production chain: multiple units stacked vertically, connected by belts.

**Function signature:**
```js
export function layoutProductionChain({
    items,             // Dict: itemName → { amount, recipeId, recipeInputs, buildingName, buildingItemId, machineCount }
    topologicalOrder,  // string[] — items sorted upstream-first
    externalInputs,    // string[] — items from outside (ores)
    finalOutputs,      // string[] — target products
    beltItemId,        // belt tier
    sorterItemId,      // sorter tier
}) => { buildings: Building[], inputPorts: Port[], outputPorts: Port[] }
```

This function:
1. Iterates through topologicalOrder
2. For each item, calls layoutProductionUnit
3. Offsets each unit vertically (stacking)
4. Reindexes all buildings to have globally unique indices
5. Connects upstream output ports to downstream input ports
6. Collects external input ports and final output ports

## Tests

Write `dsp-calc/src/blueprint/__tests__/layout_engine.test.js`:

```js
import { describe, it, expect } from 'vitest';
import { layoutProductionUnit, layoutProductionChain } from '../layout_engine.js';
import { BUILDING_IDS, BELT_IDS, SORTER_IDS } from '../constants.js';

describe('layoutProductionUnit', () => {
    it('lays out a single assembler with input/output belts', () => {
        const result = layoutProductionUnit({
            buildingItemId: BUILDING_IDS.ASSEMBLER_MK1,
            recipeId: 1,
            machineCount: 1,
            inputItems: ['铁矿'],
            outputItems: ['铁块'],
            beltItemId: BELT_IDS.MK3,
            sorterItemId: SORTER_IDS.MK2,
        });

        expect(result.buildings).toBeInstanceOf(Array);
        expect(result.buildings.length).toBeGreaterThan(0);

        const assemblers = result.buildings.filter(b => b.itemId === BUILDING_IDS.ASSEMBLER_MK1);
        expect(assemblers.length).toBe(1);

        const belts = result.buildings.filter(b =>
            b.itemId === BELT_IDS.MK1 || b.itemId === BELT_IDS.MK2 || b.itemId === BELT_IDS.MK3
        );
        expect(belts.length).toBeGreaterThan(0);

        for (const b of result.buildings) {
            expect(b.localOffset).toBeDefined();
            expect(b.localOffset[0]).toHaveProperty('x');
            expect(b.localOffset[0]).toHaveProperty('y');
            expect(b.localOffset[0]).toHaveProperty('z');
        }
    });

    it('lays out 4 assemblers in a row', () => {
        const result = layoutProductionUnit({
            buildingItemId: BUILDING_IDS.ASSEMBLER_MK1,
            recipeId: 1,
            machineCount: 4,
            inputItems: ['铁块', '铜块'],
            outputItems: ['电路板'],
            beltItemId: BELT_IDS.MK3,
            sorterItemId: SORTER_IDS.MK2,
        });

        const assemblers = result.buildings.filter(b => b.itemId === BUILDING_IDS.ASSEMBLER_MK1);
        expect(assemblers.length).toBe(4);

        const xs = assemblers.map(a => a.localOffset[0].x);
        const uniqueXs = [...new Set(xs)];
        expect(uniqueXs.length).toBe(4);
    });

    it('includes input and output port positions', () => {
        const result = layoutProductionUnit({
            buildingItemId: BUILDING_IDS.ASSEMBLER_MK1,
            recipeId: 1,
            machineCount: 2,
            inputItems: ['铁矿'],
            outputItems: ['铁块'],
            beltItemId: BELT_IDS.MK3,
            sorterItemId: SORTER_IDS.MK2,
        });

        expect(result.inputPorts).toBeDefined();
        expect(result.inputPorts.length).toBe(1);
        expect(result.outputPorts).toBeDefined();
        expect(result.outputPorts.length).toBe(1);
    });
});

describe('layoutProductionChain', () => {
    it('lays out a two-step chain (smelter → assembler)', () => {
        const chainInput = {
            items: {
                '铁块': { amount: 60, recipeId: 1, recipeInputs: ['铁矿'], buildingName: '电弧熔炉', buildingItemId: BUILDING_IDS.ARC_SMELTER, machineCount: 2 },
                '齿轮': { amount: 30, recipeId: 2, recipeInputs: ['铁块'], buildingName: '制造台 Mk.I', buildingItemId: BUILDING_IDS.ASSEMBLER_MK1, machineCount: 1 },
            },
            topologicalOrder: ['铁块', '齿轮'],
            externalInputs: ['铁矿'],
            finalOutputs: ['齿轮'],
            beltItemId: BELT_IDS.MK3,
            sorterItemId: SORTER_IDS.MK2,
        };

        const result = layoutProductionChain(chainInput);

        expect(result.buildings).toBeInstanceOf(Array);
        expect(result.buildings.length).toBeGreaterThan(0);

        const smelters = result.buildings.filter(b => b.itemId === BUILDING_IDS.ARC_SMELTER);
        const assemblers = result.buildings.filter(b => b.itemId === BUILDING_IDS.ASSEMBLER_MK1);
        expect(smelters.length).toBe(2);
        expect(assemblers.length).toBe(1);

        const indices = result.buildings.map(b => b.index);
        expect(new Set(indices).size).toBe(indices.length);
    });

    it('reports external input ports and final output ports', () => {
        const chainInput = {
            items: {
                '铁块': { amount: 60, recipeId: 1, recipeInputs: ['铁矿'], buildingName: '电弧熔炉', buildingItemId: BUILDING_IDS.ARC_SMELTER, machineCount: 2 },
            },
            topologicalOrder: ['铁块'],
            externalInputs: ['铁矿'],
            finalOutputs: ['铁块'],
            beltItemId: BELT_IDS.MK3,
            sorterItemId: SORTER_IDS.MK2,
        };

        const result = layoutProductionChain(chainInput);
        expect(result.inputPorts.some(p => p.item === '铁矿')).toBe(true);
        expect(result.outputPorts.some(p => p.item === '铁块')).toBe(true);
    });
});
```

## Implementation Notes

- Import `BUILDING_SIZE` and `BUILDING_NAME_TO_ID` from `./constants.js`
- Use `BUILDING_SIZE[buildingItemId]` to get building dimensions (default to {w:3, h:3} if not found)
