```js
import { BUILDING_NAME_TO_ID } from './constants.js';

export function extractChainFromCalcResult({
    resultDict,     // { itemName: productionAmount }
    itemGraph,      // global_state.item_graph
    itemList,       // global_state.item_list (topologically sorted)
    itemData,       // global_state.item_data
    schemeData,     // global_state.scheme_data
    gameData,       // global_state.game_data
    mineralizeList, // settings.mineralize_list
    needsList,      // user's production needs
    timeTick,       // 60 if per-minute, 1 if per-second
}) {
    const items = {};
    const topologicalOrder = [];
    const externalInputs = [];
    const finalOutputs = Object.keys(needsList);

    for (const itemName of itemList) {
        if (!(itemName in resultDict) || resultDict[itemName] < 1e-6) continue;

        const recipeIndex = itemData[itemName][schemeData.item_recipe_choices[itemName]];
        const recipe = gameData.recipe_data[recipeIndex];
        const recipeInputs = Object.keys(recipe['原料']);

        // Items with no inputs or mineralized = external input
        if (recipeInputs.length === 0 || itemName in mineralizeList) {
            if (!externalInputs.includes(itemName)) externalInputs.push(itemName);
            continue;
        }

        const factoryTypeIndex = recipe['设施'];
        const buildingIndex = schemeData.scheme_for_recipe[recipeIndex]['建筑'];
        const factoryInfo = gameData.factory_data[factoryTypeIndex][buildingIndex];
        const factoryName = factoryInfo['名称'];
        const buildingItemId = BUILDING_NAME_TO_ID[factoryName];
        if (!buildingItemId) continue;

        const factoryPerYield = 1 / itemGraph[itemName]['产出倍率'] / factoryInfo['倍率'];
        const machineCount = Math.ceil(resultDict[itemName] / timeTick * factoryPerYield);
        if (machineCount <= 0) continue;

        items[itemName] = {
            amount: resultDict[itemName],
            recipeId: recipeIndex,
            recipeInputs: recipeInputs.filter(m => !(m in mineralizeList)),
            buildingName: factoryName,
            buildingItemId,
            machineCount,
        };
        topologicalOrder.push(itemName);
    }

    for (const itemName of Object.keys(mineralizeList)) {
        if (!externalInputs.includes(itemName)) externalInputs.push(itemName);
    }

    return { items, topologicalOrder, externalInputs, finalOutputs };
}
```

