1	/**
2	 * Blueprint Encoder for Dyson Sphere Program
3	 * Ports the toStr() function from huww98/dsp_blueprint_editor/src/blueprint/parser.ts
4	 * Generates valid DSP blueprint strings from a building array.
5	 */
6	
7	import pako from 'pako';
8	import { md5f } from './md5f.js';
9	
10	// .NET epoch: ticks since 0001-01-01 00:00:00 UTC
11	// JavaScript Date(0) = 1970-01-01, which is 621355968000000000 ticks since .NET epoch
12	const TIME_BASE_MS = new Date(0).setUTCFullYear(1); // ms since JS epoch for year 0001-01-01
13	
14	// ──────────────────────────────────────────────
15	// BufferWriter — sequential little-endian writes
16	// ──────────────────────────────────────────────
17	class BufferWriter {
18	    constructor(view) {
19	        this.view = view;
20	        this.pos = 0;
21	    }
22	
23	    setUint8(value) { this.view.setUint8(this.pos, value);        this.pos += 1; }
24	    setInt8(value)  { this.view.setInt8(this.pos, value);         this.pos += 1; }
25	    setInt16(value) { this.view.setInt16(this.pos, value, true);  this.pos += 2; }
26	    setInt32(value) { this.view.setInt32(this.pos, value, true);  this.pos += 4; }
27	    setFloat32(value) { this.view.setFloat32(this.pos, value, true); this.pos += 4; }
28	
29	    /** Return a DataView slice of `length` bytes at current position, advancing pos. */
30	    getView(length) {
31	        const r = new DataView(this.view.buffer, this.view.byteOffset + this.pos, length);
32	        this.pos += length;
33	        return r;
34	    }
35	}
36	
37	// ──────────────────────────────────────────────
38	// Binary size calculation
39	// ──────────────────────────────────────────────
40	
41	/**
42	 * Calculate the number of int32 parameters for a building.
43	 * If parameters is null, returns 0.
44	 * If parameters is an array, returns its length.
45	 * Otherwise treat as raw paramCount from the object if present.
46	 */
47	function paramCount(building) {
48	    if (building.parameters === null || building.parameters === undefined) return 0;
49	    if (Array.isArray(building.parameters)) return building.parameters.length;
50	    // Raw int32 array stored as typed array
51	    if (building.parameters instanceof Int32Array) return building.parameters.length;
52	    // Fallback: unknown object, skip
53	    return 0;
54	}
55	
56	/**
57	 * Compute total binary buffer size needed for the blueprint payload.
58	 * Layout (all little-endian):
59	 *   28 bytes  — 7× int32 meta fields
60	 *    1 byte   — uint8 areaCount
61	 *   14 × N   — areas
62	 *    4 bytes  — int32 buildingCount
63	 *   (61 + 4*paramCount) per building
64	 */
65	function encodedSize(bp) {
66	    let size = 28  // version + cursorOffset(x,y) + cursorTargetArea + dragBoxSize(x,y) + primaryAreaIdx
67	        + 1                              // areaCount uint8
68	        + 14 * bp.areas.length           // each area is 14 bytes
69	        + 4                              // buildingCount int32
70	        + 61 * bp.buildings.length;      // fixed part per building
71	
72	    for (const b of bp.buildings) {
73	        const pc = paramCount(b);
74	        size += pc * 4; // each int32 param = 4 bytes
75	    }
76	    return size;
77	}
78	
79	// ──────────────────────────────────────────────
80	// Area serializer
81	// ──────────────────────────────────────────────
82	
83	function exportArea(w, area) {
84	    w.setInt8(area.index);
85	    w.setInt8(area.parentIndex);
86	    w.setInt16(area.tropicAnchor);
87	    w.setInt16(area.areaSegments);
88	    w.setInt16(area.anchorLocalOffset.x);
89	    w.setInt16(area.anchorLocalOffset.y);
90	    w.setInt16(area.size.x);
91	    w.setInt16(area.size.y);
92	}
93	
94	// ──────────────────────────────────────────────
95	// Building serializer
96	// ──────────────────────────────────────────────
97	
98	function exportBuilding(w, b) {
99	    function writeXYZ(v) {
100	        w.setFloat32(v.x);
101	        w.setFloat32(v.y);
102	        w.setFloat32(v.z);
103	    }
104	
105	    w.setInt32(b.index);
106	    w.setInt8(b.areaIndex);
107	    writeXYZ(b.localOffset[0]);
108	    writeXYZ(b.localOffset[1]);
109	    w.setFloat32(b.yaw[0]);
110	    w.setFloat32(b.yaw[1]);
111	    w.setInt16(b.itemId);
112	    w.setInt16(b.modelIndex);
113	    w.setInt32(b.outputObjIdx);
114	    w.setInt32(b.inputObjIdx);
115	    w.setInt8(b.outputToSlot);
116	    w.setInt8(b.inputFromSlot);
117	    w.setInt8(b.outputFromSlot);
118	    w.setInt8(b.inputToSlot);
119	    w.setInt8(b.outputOffset);
120	    w.setInt8(b.inputOffset);
121	    w.setInt16(b.recipeId);
122	    w.setInt16(b.filterId);
123	
124	    const pc = paramCount(b);
125	    w.setInt16(pc);
126	
127	    if (pc > 0) {
128	        const view = w.getView(pc * 4);
129	        const params = b.parameters;
130	        if (params instanceof Int32Array) {
131	            for (let i = 0; i < pc; i++) {
132	                view.setInt32(i * 4, params[i], true);
133	            }
134	        } else if (Array.isArray(params)) {
135	            for (let i = 0; i < pc; i++) {
136	                view.setInt32(i * 4, params[i], true);
137	            }
138	        }
139	    }
140	}
141	
142	// ──────────────────────────────────────────────
143	// Uint8Array ↔ binary string helpers
144	// (mirrors huww98's btoUint8Array / Uint8ArrayTob)
145	// ──────────────────────────────────────────────
146	
147	function uint8ArrayToBinaryString(a) {
148	    let out = '';
149	    for (let i = 0; i < a.length; i++) {
150	        out += String.fromCharCode(a[i]);
151	    }
152	    return out;
153	}
154	
155	function binaryStringToUint8Array(b) {
156	    const arr = new Uint8Array(b.length);
157	    for (let i = 0; i < b.length; i++) {
158	        arr[i] = b.charCodeAt(i);
159	    }
160	    return arr;
161	}
162	
163	// ──────────────────────────────────────────────
164	// Public API
165	// ──────────────────────────────────────────────
166	
167	/**
168	 * Create an empty BlueprintData structure with sensible defaults.
169	 *
170	 * @param {object} opts
171	 * @param {string} [opts.shortDesc='']
172	 * @param {string} [opts.desc='']
173	 * @param {string} [opts.gameVersion='0.0.0.0']
174	 * @returns {object} BlueprintData
175	 */
176	export function createEmptyBlueprint({ shortDesc = '', desc = '', gameVersion = '0.0.0.0' } = {}) {
177	    return {
178	        header: {
179	            layout: 0,
180	            icons: [0, 0, 0, 0, 0],
181	            time: new Date(),
182	            gameVersion,
183	            shortDesc,
184	            desc,
185	        },
186	        version: 1,
187	        cursorOffset: { x: 0, y: 0 },
188	        cursorTargetArea: 0,
189	        dragBoxSize: { x: 1, y: 1 },
190	        primaryAreaIdx: 0,
191	        areas: [
192	            {
193	                index: 0,
194	                parentIndex: -1,
195	                tropicAnchor: 0,
196	                areaSegments: 200,
197	                anchorLocalOffset: { x: 0, y: 0 },
198	                size: { x: 1, y: 1 },
199	            },
200	        ],
201	        buildings: [],
202	    };
203	}
204	
205	/**
206	 * Encode a BlueprintData object into the DSP blueprint string format.
207	 *
208	 * Format: BLUEPRINT:0,{header}"<base64-gzipped-binary>"{MD5F-hash}
209	 *
210	 * @param {object} bp — BlueprintData as returned by createEmptyBlueprint()
211	 * @returns {string} The full blueprint string
212	 */
213	export function encodeBlueprintString(bp) {
214	    // ── 1. Build the text header ──────────────────────────────────────────
215	    // Format: BLUEPRINT:0,{layout},{icon0},{icon1},{icon2},{icon3},{icon4},0,{ticks},{gameVersion},{shortDesc},{desc}"
216	    const h = bp.header;
217	
218	    // Convert JS timestamp to .NET ticks
219	    // ticks = (ms - TIME_BASE_MS) * 10000
220	    const ticksMs = h.time.getTime() - TIME_BASE_MS;
221	    // Use BigInt to avoid float precision loss, then convert back to string
222	    const ticks = (BigInt(Math.round(ticksMs)) * 10000n).toString();
223	
224	    let result = 'BLUEPRINT:0,';
225	    result += h.layout + ',';
226	    for (const icon of h.icons) {
227	        result += icon + ',';
228	    }
229	    result += '0,';
230	    result += ticks + ',';
231	    result += h.gameVersion + ',';
232	    result += encodeURIComponent(h.shortDesc) + ',';
233	    result += encodeURIComponent(h.desc);
234	    result += '"';
235	
236	    // ── 2. Serialize binary payload ───────────────────────────────────────
237	    const bufSize = encodedSize(bp);
238	    const buffer = new ArrayBuffer(bufSize);
239	    const writer = new BufferWriter(new DataView(buffer));
240	
241	    writer.setInt32(bp.version);
242	    writer.setInt32(bp.cursorOffset.x);
243	    writer.setInt32(bp.cursorOffset.y);
244	    writer.setInt32(bp.cursorTargetArea);
245	    writer.setInt32(bp.dragBoxSize.x);
246	    writer.setInt32(bp.dragBoxSize.y);
247	    writer.setInt32(bp.primaryAreaIdx);
248	
249	    writer.setUint8(bp.areas.length);
