/**
 * Blueprint Encoder for Dyson Sphere Program
 * Ports the toStr() function from huww98/dsp_blueprint_editor/src/blueprint/parser.ts
 * Generates valid DSP blueprint strings from a building array.
 */

import pako from 'pako';
import { md5f } from './md5f.js';

// .NET epoch: ticks since 0001-01-01 00:00:00 UTC
// JavaScript Date(0) = 1970-01-01, which is 621355968000000000 ticks since .NET epoch
const TIME_BASE_MS = new Date(0).setUTCFullYear(1); // ms since JS epoch for year 0001-01-01

// ──────────────────────────────────────────────
// BufferWriter — sequential little-endian writes
// ──────────────────────────────────────────────
class BufferWriter {
    constructor(view) {
        this.view = view;
        this.pos = 0;
    }

    setUint8(value) { this.view.setUint8(this.pos, value);        this.pos += 1; }
    setInt8(value)  { this.view.setInt8(this.pos, value);         this.pos += 1; }
    setInt16(value) { this.view.setInt16(this.pos, value, true);  this.pos += 2; }
    setInt32(value) { this.view.setInt32(this.pos, value, true);  this.pos += 4; }
    setFloat32(value) { this.view.setFloat32(this.pos, value, true); this.pos += 4; }

    /** Return a DataView slice of `length` bytes at current position, advancing pos. */
    getView(length) {
        const r = new DataView(this.view.buffer, this.view.byteOffset + this.pos, length);
        this.pos += length;
        return r;
    }
}

// ──────────────────────────────────────────────
// Binary size calculation
// ──────────────────────────────────────────────

/**
 * Calculate the number of int32 parameters for a building.
 * If parameters is null, returns 0.
 * If parameters is an array, returns its length.
 * Otherwise treat as raw paramCount from the object if present.
 */
function paramCount(building) {
    if (building.parameters === null || building.parameters === undefined) return 0;
    if (Array.isArray(building.parameters)) return building.parameters.length;
    // Raw int32 array stored as typed array
    if (building.parameters instanceof Int32Array) return building.parameters.length;
    // Fallback: unknown object, skip
    return 0;
}

/**
 * Compute total binary buffer size needed for the blueprint payload.
 * Layout (all little-endian):
 *   28 bytes  — 7× int32 meta fields
 *    1 byte   — uint8 areaCount
 *   14 × N   — areas
 *    4 bytes  — int32 buildingCount
 *   (61 + 4*paramCount) per building
 */
function encodedSize(bp) {
    let size = 28  // version + cursorOffset(x,y) + cursorTargetArea + dragBoxSize(x,y) + primaryAreaIdx
        + 1                              // areaCount uint8
        + 14 * bp.areas.length           // each area is 14 bytes
        + 4                              // buildingCount int32
        + 61 * bp.buildings.length;      // fixed part per building

    for (const b of bp.buildings) {
        const pc = paramCount(b);
        size += pc * 4; // each int32 param = 4 bytes
    }
    return size;
}

// ──────────────────────────────────────────────
// Area serializer
// ──────────────────────────────────────────────

function exportArea(w, area) {
    w.setInt8(area.index);
    w.setInt8(area.parentIndex);
    w.setInt16(area.tropicAnchor);
    w.setInt16(area.areaSegments);
    w.setInt16(area.anchorLocalOffset.x);
    w.setInt16(area.anchorLocalOffset.y);
    w.setInt16(area.size.x);
    w.setInt16(area.size.y);
}

// ──────────────────────────────────────────────
// Building serializer
// ──────────────────────────────────────────────

function exportBuilding(w, b) {
    function writeXYZ(v) {
        w.setFloat32(v.x);
        w.setFloat32(v.y);
        w.setFloat32(v.z);
    }

    w.setInt32(b.index);
    w.setInt8(b.areaIndex);
    writeXYZ(b.localOffset[0]);
    writeXYZ(b.localOffset[1]);
    w.setFloat32(b.yaw[0]);
    w.setFloat32(b.yaw[1]);
    w.setInt16(b.itemId);
    w.setInt16(b.modelIndex);
    w.setInt32(b.outputObjIdx);
    w.setInt32(b.inputObjIdx);
    w.setInt8(b.outputToSlot);
    w.setInt8(b.inputFromSlot);
    w.setInt8(b.outputFromSlot);
    w.setInt8(b.inputToSlot);
    w.setInt8(b.outputOffset);
    w.setInt8(b.inputOffset);
    w.setInt16(b.recipeId);
    w.setInt16(b.filterId);

    const pc = paramCount(b);
    w.setInt16(pc);

    if (pc > 0) {
        const view = w.getView(pc * 4);
        const params = b.parameters;
        if (params instanceof Int32Array) {
            for (let i = 0; i < pc; i++) {
                view.setInt32(i * 4, params[i], true);
            }
        } else if (Array.isArray(params)) {
            for (let i = 0; i < pc; i++) {
                view.setInt32(i * 4, params[i], true);
            }
        }
    }
}

// ──────────────────────────────────────────────
// Uint8Array ↔ binary string helpers
// (mirrors huww98's btoUint8Array / Uint8ArrayTob)
// ──────────────────────────────────────────────

function uint8ArrayToBinaryString(a) {
    let out = '';
    for (let i = 0; i < a.length; i++) {
        out += String.fromCharCode(a[i]);
    }
    return out;
}

function binaryStringToUint8Array(b) {
    const arr = new Uint8Array(b.length);
    for (let i = 0; i < b.length; i++) {
        arr[i] = b.charCodeAt(i);
    }
    return arr;
}

// ──────────────────────────────────────────────
// Public API
// ──────────────────────────────────────────────

/**
 * Create an empty BlueprintData structure with sensible defaults.
 *
 * @param {object} opts
 * @param {string} [opts.shortDesc='']
 * @param {string} [opts.desc='']
 * @param {string} [opts.gameVersion='0.0.0.0']
 * @returns {object} BlueprintData
 */
export function createEmptyBlueprint({ shortDesc = '', desc = '', gameVersion = '0.0.0.0' } = {}) {
    return {
        header: {
            layout: 0,
            icons: [0, 0, 0, 0, 0],
            time: new Date(),
            gameVersion,
            shortDesc,
            desc,
        },
        version: 1,
        cursorOffset: { x: 0, y: 0 },
        cursorTargetArea: 0,
        dragBoxSize: { x: 1, y: 1 },
        primaryAreaIdx: 0,
        areas: [
            {
                index: 0,
                parentIndex: -1,
                tropicAnchor: 0,
                areaSegments: 200,
                anchorLocalOffset: { x: 0, y: 0 },
                size: { x: 1, y: 1 },
            },
        ],
        buildings: [],
    };
}

/**
 * Encode a BlueprintData object into the DSP blueprint string format.
 *
 * Format: BLUEPRINT:0,{header}"<base64-gzipped-binary>"{MD5F-hash}
 *
 * @param {object} bp — BlueprintData as returned by createEmptyBlueprint()
 * @returns {string} The full blueprint string
 */
export function encodeBlueprintString(bp) {
    // ── 1. Build the text header ──────────────────────────────────────────
    // Format: BLUEPRINT:0,{layout},{icon0},{icon1},{icon2},{icon3},{icon4},0,{ticks},{gameVersion},{shortDesc},{desc}"
    const h = bp.header;

    // Convert JS timestamp to .NET ticks
    // ticks = (ms - TIME_BASE_MS) * 10000
    const ticksMs = h.time.getTime() - TIME_BASE_MS;
    // Use BigInt to avoid float precision loss, then convert back to string
    const ticks = (BigInt(Math.round(ticksMs)) * 10000n).toString();

    let result = 'BLUEPRINT:0,';
    result += h.layout + ',';
    for (const icon of h.icons) {
        result += icon + ',';
    }
    result += '0,';
    result += ticks + ',';
    result += h.gameVersion + ',';
    result += encodeURIComponent(h.shortDesc) + ',';
    result += encodeURIComponent(h.desc);
    result += '"';

    // ── 2. Serialize binary payload ───────────────────────────────────────
    const bufSize = encodedSize(bp);
    const buffer = new ArrayBuffer(bufSize);
    const writer = new BufferWriter(new DataView(buffer));

    writer.setInt32(bp.version);
    writer.setInt32(bp.cursorOffset.x);
    writer.setInt32(bp.cursorOffset.y);
    writer.setInt32(bp.cursorTargetArea);
    writer.setInt32(bp.dragBoxSize.x);
    writer.setInt32(bp.dragBoxSize.y);
    writer.setInt32(bp.primaryAreaIdx);

    writer.setUint8(bp.areas.length);
    for (const area of bp.areas) {
        exportArea(writer, area);
    }

    writer.setInt32(bp.buildings.length);
    for (const building of bp.buildings) {
        exportBuilding(writer, building);
    }

    // ── 3. gzip + base64 ─────────────────────────────────────────────────
    const compressed = pako.gzip(new Uint8Array(buffer));
    const base64 = btoa(uint8ArrayToBinaryString(compressed));
    result += base64;

    // ── 4. Compute MD5F over everything up to (but not including) the closing quote
    //       then append: '"' + hash
    const hash = md5f(result);
    result += '"';
    result += hash;

    return result;
}

