109	    // --- Sorters: machine → output belt ---
110	    for (let i = 0; i < machineCount; i++) {
111	        const idx = nextIndex++;
112	        const sorter = makeBuilding(idx, sorterItemId, i * bw, outputBeltY + 1, 0);
