114	        sorter.inputObjIdx = machineIndices[i];
115	        buildings.push(sorter);
116	    }
117	
118	    // --- Input belt 0 ---
119	    const inputBelt0Indices = [];
120	    for (let i = 0; i < machineCount; i++) {
121	        const x = i * bw;
122	        const idx = nextIndex++;
123	        buildings.push(makeBuilding(idx, beltItemId, x, inputBelt0Y, 0));
124	        inputBelt0Indices.push(idx);
125	    }
126	
127	    // Chain input belt 0 segments
128	    for (let i = 0; i < inputBelt0Indices.length - 1; i++) {
129	        buildings[inputBelt0Indices[i]].outputObjIdx = inputBelt0Indices[i + 1];
130	        buildings[inputBelt0Indices[i + 1]].inputObjIdx = inputBelt0Indices[i];
131	    }
132	
133	    // --- Sorters: input belt 0 → machine ---
134	    for (let i = 0; i < machineCount; i++) {
135	        const idx = nextIndex++;
136	        const sorter = makeBuilding(idx, sorterItemId, i * bw, inputBelt0Y - 1, 0);
137	        sorter.outputObjIdx = machineIndices[i];
138	        sorter.inputObjIdx = inputBelt0Indices[i];
139	        buildings.push(sorter);
140	    }
141	
142	    // --- Input belt 1 (if 2 inputs) ---
