144	    if (numInputs >= 2) {
145	        for (let i = 0; i < machineCount; i++) {
146	            const x = i * bw;
147	            const idx = nextIndex++;
148	            buildings.push(makeBuilding(idx, beltItemId, x, inputBelt1Y, 0));
