209	 * @param {object} params.items  Dict: itemName → { amount, recipeId, recipeInputs, buildingName, buildingItemId, machineCount }
210	 * @param {string[]} params.topologicalOrder  items sorted upstream-first
211	 * @param {string[]} params.externalInputs    items from outside (ores)
212	 * @param {string[]} params.finalOutputs      target products
213	 * @param {number} params.beltItemId
214	 * @param {number} params.sorterItemId
215	 * @returns {{ buildings: object[], inputPorts: object[], outputPorts: object[] }}
216	 */
217	export function layoutProductionChain({
218	    items,
219	    topologicalOrder,
220	    externalInputs,
221	    finalOutputs,
222	    beltItemId,
223	    sorterItemId,
224	}) {
225	    const GAP = 2; // grid units between stacked units
226	
227	    let allBuildings = [];
228	    let globalIndexOffset = 0;
229	    let currentY = 0;
230	
231	    // Track ports by item name so we can connect them
232	    // outputPortsByItem: itemName → port (with absolute position and beltIndex in allBuildings)
233	    const outputPortsByItem = {};
234	
235	    // Collected external input ports and final output ports
236	    const externalInputPortsMap = {}; // itemName → port (first occurrence wins)
237	    const finalOutputPortsMap = {};   // itemName → port
238	
239	    const externalInputSet = new Set(externalInputs);
240	    const finalOutputSet = new Set(finalOutputs);
241	
242	    for (const itemName of topologicalOrder) {
243	        const itemData = items[itemName];
244	        if (!itemData) continue;
245	
246	        const {
247	            recipeId,
248	            recipeInputs = [],
249	            buildingItemId,
250	            machineCount,
251	        } = itemData;
252	
253	        const unit = layoutProductionUnit({
254	            buildingItemId,
255	            recipeId,
256	            machineCount,
257	            inputItems: recipeInputs,
258	            outputItems: [itemName],
259	            beltItemId,
260	            sorterItemId,
261	        });
262	
263	        // Offset all buildings in this unit by currentY and globalIndexOffset
264	        const offsetBuildings = unit.buildings.map(b => {
265	            const ob = { ...b };
266	            ob.localOffset = [
267	                { ...b.localOffset[0], y: b.localOffset[0].y + currentY },
268	                { ...b.localOffset[1], y: b.localOffset[1].y + currentY },
269	            ];
270	            ob.index = b.index + globalIndexOffset;
271	            if (b.outputObjIdx !== -1) ob.outputObjIdx = b.outputObjIdx + globalIndexOffset;
272	            if (b.inputObjIdx !== -1) ob.inputObjIdx = b.inputObjIdx + globalIndexOffset;
273	            return ob;
274	        });
275	
276	        // Offset port beltIndex values and positions
277	        const offsetInputPorts = unit.inputPorts.map(p => ({
278	            ...p,
279	            beltIndex: p.beltIndex + globalIndexOffset,
280	            position: { ...p.position, y: p.position.y + currentY },
281	        }));
282	
283	        const offsetOutputPorts = unit.outputPorts.map(p => ({
284	            ...p,
285	            beltIndex: p.beltIndex + globalIndexOffset,
286	            position: { ...p.position, y: p.position.y + currentY },
287	        }));
288	
289	        // Register output ports for connection to downstream units
290	        for (const port of offsetOutputPorts) {
291	            outputPortsByItem[port.item] = { ...port, buildingsList: offsetBuildings };
292	        }
293	
294	        // Connect input ports to upstream output ports
295	        for (const port of offsetInputPorts) {
296	            const upstreamPort = outputPortsByItem[port.item];
297	            if (upstreamPort) {
298	                // Connect the upstream output belt end to this input belt start
299	                // Find the rightmost upstream output belt segment and connect it
300	                // to the leftmost downstream input belt segment via outputObjIdx/inputObjIdx
301	                const upstreamBeltBuilding = allBuildings.find(b => b.index === upstreamPort.beltIndex);
302	                const downstreamBeltBuilding = offsetBuildings.find(b => b.index === port.beltIndex);
303	                if (upstreamBeltBuilding && downstreamBeltBuilding) {
304	                    upstreamBeltBuilding.outputObjIdx = downstreamBeltBuilding.index;
305	                    downstreamBeltBuilding.inputObjIdx = upstreamBeltBuilding.index;
306	                }
307	            }
308	
309	            // Collect external input ports
310	            if (externalInputSet.has(port.item)) {
311	                if (!externalInputPortsMap[port.item]) {
312	                    externalInputPortsMap[port.item] = port;
313	                }
314	            }
315	        }
316	
317	        // Collect final output ports
318	        for (const port of offsetOutputPorts) {
319	            if (finalOutputSet.has(port.item)) {
320	                if (!finalOutputPortsMap[port.item]) {
321	                    finalOutputPortsMap[port.item] = port;
322	                }
323	            }
324	        }
325	
326	        allBuildings = allBuildings.concat(offsetBuildings);
327	
328	        globalIndexOffset += unit.buildings.length;
329	        currentY += unit.height + GAP;
330	    }
331	
332	    return {
333	        buildings: allBuildings,
334	        inputPorts: Object.values(externalInputPortsMap),
335	        outputPorts: Object.values(finalOutputPortsMap),
336	    };
337	}
