import { BUILDING_SIZE } from './constants.js';

/**
 * Create a default building object with all required fields.
 */
function makeBuilding(index, itemId, x, y, z, recipeId = 0) {
    return {
        index,
        areaIndex: 0,
        localOffset: [
            { x, y, z },
            { x, y, z },
        ],
        yaw: [0, 0],
        itemId,
        modelIndex: 0,
        outputObjIdx: -1,
        inputObjIdx: -1,
        outputToSlot: 0,
        inputFromSlot: 0,
        outputFromSlot: 0,
        inputToSlot: 0,
        outputOffset: 0,
        inputOffset: 0,
        recipeId,
        filterId: 0,
        parameters: null,
    };
}

/**
 * Lay out ONE recipe's worth of buildings:
 *   N machines in a row with input/output belts and sorters.
 *
 * Grid layout (Y increases upward in DSP local coords, X increases rightward):
 *
 *   y = outputBeltY  : output belt row  (belt segments spanning machine width)
 *   y = machineY     : machine row
 *   y = inputBelt0Y  : input belt 0 row
 *   y = inputBelt1Y  : input belt 1 row (if 2 inputs)
 *
 * All buildings are placed with z = 0.
 *
 * @param {object} params
 * @param {number} params.buildingItemId
 * @param {number} params.recipeId
 * @param {number} params.machineCount
 * @param {string[]} params.inputItems
 * @param {string[]} params.outputItems
 * @param {number} params.beltItemId
 * @param {number} params.sorterItemId
 * @returns {{ buildings: object[], inputPorts: object[], outputPorts: object[], width: number, height: number }}
 */
export function layoutProductionUnit({
    buildingItemId,
    recipeId,
    machineCount,
    inputItems,
    outputItems,
    beltItemId,
    sorterItemId,
}) {
    const size = BUILDING_SIZE[buildingItemId] ?? { w: 3, h: 3 };
    const bw = size.w; // building width (grid units)
    const bh = size.h; // building height (grid units)

    const numInputs = Math.min(inputItems.length, 2); // cap at 2 per spec

    // Y positions (bottom-up layout)
    // Row 0 (bottom): output belt
    const outputBeltY = 0;
    // Row 1: machines
    const machineY = bh;
    // Row 2: input belt 0
    const inputBelt0Y = machineY + bh;
    // Row 3: input belt 1 (if needed)
    const inputBelt1Y = inputBelt0Y + 2; // 2 units above input belt 0

    const totalWidth = machineCount * bw;

    const buildings = [];
    let nextIndex = 0;

    // --- Machines ---
    const machineIndices = [];
    for (let i = 0; i < machineCount; i++) {
        const x = i * bw;
        const idx = nextIndex++;
        buildings.push(makeBuilding(idx, buildingItemId, x, machineY, 0, recipeId));
        machineIndices.push(idx);
    }

    // --- Output belt segments ---
    // One belt segment per machine column at outputBeltY
    const outputBeltIndices = [];
    for (let i = 0; i < machineCount; i++) {
        const x = i * bw;
        const idx = nextIndex++;
        buildings.push(makeBuilding(idx, beltItemId, x, outputBeltY, 0));
        outputBeltIndices.push(idx);
    }

    // Chain output belt segments left-to-right (each feeds into next)
    for (let i = 0; i < outputBeltIndices.length - 1; i++) {
        buildings[outputBeltIndices[i]].outputObjIdx = outputBeltIndices[i + 1];
        buildings[outputBeltIndices[i + 1]].inputObjIdx = outputBeltIndices[i];
    }

    // --- Sorters: machine → output belt ---
    for (let i = 0; i < machineCount; i++) {
        const idx = nextIndex++;
        const sorter = makeBuilding(idx, sorterItemId, i * bw, outputBeltY + 1, 0);
        sorter.outputObjIdx = outputBeltIndices[i];
        sorter.inputObjIdx = machineIndices[i];
        buildings.push(sorter);
    }

    // --- Input belt 0 ---
    const inputBelt0Indices = [];
    for (let i = 0; i < machineCount; i++) {
        const x = i * bw;
        const idx = nextIndex++;
        buildings.push(makeBuilding(idx, beltItemId, x, inputBelt0Y, 0));
        inputBelt0Indices.push(idx);
    }

    // Chain input belt 0 segments
    for (let i = 0; i < inputBelt0Indices.length - 1; i++) {
        buildings[inputBelt0Indices[i]].outputObjIdx = inputBelt0Indices[i + 1];
        buildings[inputBelt0Indices[i + 1]].inputObjIdx = inputBelt0Indices[i];
    }

    // --- Sorters: input belt 0 → machine ---
    for (let i = 0; i < machineCount; i++) {
        const idx = nextIndex++;
        const sorter = makeBuilding(idx, sorterItemId, i * bw, inputBelt0Y - 1, 0);
        sorter.outputObjIdx = machineIndices[i];
        sorter.inputObjIdx = inputBelt0Indices[i];
        buildings.push(sorter);
    }

    // --- Input belt 1 (if 2 inputs) ---
    const inputBelt1Indices = [];
    if (numInputs >= 2) {
        for (let i = 0; i < machineCount; i++) {
            const x = i * bw;
            const idx = nextIndex++;
            buildings.push(makeBuilding(idx, beltItemId, x, inputBelt1Y, 0));
            inputBelt1Indices.push(idx);
        }

        // Chain input belt 1 segments
        for (let i = 0; i < inputBelt1Indices.length - 1; i++) {
            buildings[inputBelt1Indices[i]].outputObjIdx = inputBelt1Indices[i + 1];
            buildings[inputBelt1Indices[i + 1]].inputObjIdx = inputBelt1Indices[i];
        }

        // Sorters: input belt 1 → machine
        for (let i = 0; i < machineCount; i++) {
            const idx = nextIndex++;
            const sorter = makeBuilding(idx, sorterItemId, i * bw, inputBelt1Y - 1, 0);
            sorter.outputObjIdx = machineIndices[i];
            sorter.inputObjIdx = inputBelt1Indices[i];
            buildings.push(sorter);
        }
    }

    // --- Ports ---
    // Input ports: leftmost belt segment of each input belt row
    const inputPorts = inputItems.slice(0, 2).map((item, i) => {
        const beltIndices = i === 0 ? inputBelt0Indices : inputBelt1Indices;
        const beltBuilding = buildings[beltIndices[0]];
        return {
            item,
            beltIndex: beltIndices[0],
            position: { ...beltBuilding.localOffset[0] },
        };
    });

    // Output port: leftmost output belt segment
    const outputPorts = outputItems.slice(0, 1).map((item) => {
        const beltBuilding = buildings[outputBeltIndices[0]];
        return {
            item,
            beltIndex: outputBeltIndices[0],
            position: { ...beltBuilding.localOffset[0] },
        };
    });

    // Compute total height
    const topY = numInputs >= 2 ? inputBelt1Y : inputBelt0Y;
    const height = topY + 1; // inclusive rows

    return {
        buildings,
        inputPorts,
        outputPorts,
        width: totalWidth,
        height,
    };
}

/**
 * Lay out a FULL production chain: multiple units stacked vertically.
 *
 * Units are stacked along the Y axis with a 2-unit gap between them.
 *
 * @param {object} params
 * @param {object} params.items  Dict: itemName → { amount, recipeId, recipeInputs, buildingName, buildingItemId, machineCount }
 * @param {string[]} params.topologicalOrder  items sorted upstream-first
 * @param {string[]} params.externalInputs    items from outside (ores)
 * @param {string[]} params.finalOutputs      target products
 * @param {number} params.beltItemId
 * @param {number} params.sorterItemId
 * @returns {{ buildings: object[], inputPorts: object[], outputPorts: object[] }}
 */
export function layoutProductionChain({
    items,
    topologicalOrder,
    externalInputs,
    finalOutputs,
    beltItemId,
    sorterItemId,
}) {
    const GAP = 2; // grid units between stacked units

    let allBuildings = [];
    let globalIndexOffset = 0;
    let currentY = 0;

    // Track ports by item name so we can connect them
    // outputPortsByItem: itemName → port (with absolute position and beltIndex in allBuildings)
    const outputPortsByItem = {};

    // Collected external input ports and final output ports
    const externalInputPortsMap = {}; // itemName → port (first occurrence wins)
    const finalOutputPortsMap = {};   // itemName → port

    const externalInputSet = new Set(externalInputs);
    const finalOutputSet = new Set(finalOutputs);

    for (const itemName of topologicalOrder) {
        const itemData = items[itemName];
        if (!itemData) continue;

        const {
            recipeId,
            recipeInputs = [],
            buildingItemId,
            machineCount,
        } = itemData;

        const unit = layoutProductionUnit({
            buildingItemId,
            recipeId,
            machineCount,
            inputItems: recipeInputs,
            outputItems: [itemName],
            beltItemId,
            sorterItemId,
        });

        // Offset all buildings in this unit by currentY and globalIndexOffset
        const offsetBuildings = unit.buildings.map(b => {
            const ob = { ...b };
            ob.localOffset = [
                { ...b.localOffset[0], y: b.localOffset[0].y + currentY },
                { ...b.localOffset[1], y: b.localOffset[1].y + currentY },
            ];
            ob.index = b.index + globalIndexOffset;
            if (b.outputObjIdx !== -1) ob.outputObjIdx = b.outputObjIdx + globalIndexOffset;
            if (b.inputObjIdx !== -1) ob.inputObjIdx = b.inputObjIdx + globalIndexOffset;
            return ob;
        });

        // Offset port beltIndex values and positions
        const offsetInputPorts = unit.inputPorts.map(p => ({
            ...p,
            beltIndex: p.beltIndex + globalIndexOffset,
            position: { ...p.position, y: p.position.y + currentY },
        }));

        const offsetOutputPorts = unit.outputPorts.map(p => ({
            ...p,
            beltIndex: p.beltIndex + globalIndexOffset,
            position: { ...p.position, y: p.position.y + currentY },
        }));

        // Register output ports for connection to downstream units
        for (const port of offsetOutputPorts) {
            outputPortsByItem[port.item] = { ...port, buildingsList: offsetBuildings };
        }

        // Connect input ports to upstream output ports
        for (const port of offsetInputPorts) {
            const upstreamPort = outputPortsByItem[port.item];
            if (upstreamPort) {
                // Connect the upstream output belt end to this input belt start
                // Find the rightmost upstream output belt segment and connect it
                // to the leftmost downstream input belt segment via outputObjIdx/inputObjIdx
                const upstreamBeltBuilding = allBuildings.find(b => b.index === upstreamPort.beltIndex);
                const downstreamBeltBuilding = offsetBuildings.find(b => b.index === port.beltIndex);
                if (upstreamBeltBuilding && downstreamBeltBuilding) {
                    upstreamBeltBuilding.outputObjIdx = downstreamBeltBuilding.index;
                    downstreamBeltBuilding.inputObjIdx = upstreamBeltBuilding.index;
                }
            }

            // Collect external input ports
            if (externalInputSet.has(port.item)) {
                if (!externalInputPortsMap[port.item]) {
                    externalInputPortsMap[port.item] = port;
                }
            }
        }

        // Collect final output ports
        for (const port of offsetOutputPorts) {
            if (finalOutputSet.has(port.item)) {
                if (!finalOutputPortsMap[port.item]) {
                    finalOutputPortsMap[port.item] = port;
                }
            }
        }

        allBuildings = allBuildings.concat(offsetBuildings);

        globalIndexOffset += unit.buildings.length;
        currentY += unit.height + GAP;
    }

    return {
        buildings: allBuildings,
        inputPorts: Object.values(externalInputPortsMap),
        outputPorts: Object.values(finalOutputPortsMap),
    };
}

