    outputOffset: 0, inputOffset: 0,
    recipeId: 0, filterId: 0, parameters: null,
});

const str = encodeBlueprintString(bp);
console.log('Blueprint string (first 200 chars):', str.substring(0, 200));
console.log('Total length:', str.length);

// Now decode it back
const parts = str.split('\"');
console.log('Parts count:', parts.length);
console.log('Header:', parts[0]);
console.log('Hash:', parts[2]);
console.log('Base64 length:', parts[1].length);

// Decode base64
const binaryStr = atob(parts[1]);
const bytes = new Uint8Array(binaryStr.length);
for (let i = 0; i < binaryStr.length; i++) bytes[i] = binaryStr.charCodeAt(i);

// Decompress
const decompressed = pako.ungzip(bytes);
console.log('Decompressed length:', decompressed.length);

// Parse binary
const view = new DataView(decompressed.buffer);
