    const idx = view.getInt32(offset, true); offset += 4;
    const areaIdx = view.getInt8(offset); offset += 1;
    const x1 = view.getFloat32(offset, true); offset += 4;
    const y1 = view.getFloat32(offset, true); offset += 4;
